pub static mut universe_hash: hash_table = unsafe { core::mem::zeroed() };

// ---- initialize_universes ----
unsafe fn initialize_universes() {
    let universe = core::ptr::addr_of_mut!(dhcp_universe);
    (*universe).name = b"dhcp\0".as_ptr() as *mut i8;
    (*universe).hash = new_hash();
    if (*universe).hash.is_null() {
        error(b"Can't allocate dhcp option hash table.\0".as_ptr() as *const i8);
    }
    for i in 0..256 {
        (*universe).options[i] = core::ptr::addr_of_mut!(dhcp_options[i]);
        add_hash(
            (*universe).hash,
            core::ptr::addr_of!(dhcp_options[i].name) as *mut u8,
            0,
            core::ptr::addr_of_mut!(dhcp_options[i]) as *mut u8,
        );
    }
    let hash = core::ptr::addr_of_mut!(universe_hash);
    (*hash).hash_count = (DEFAULT_HASH_SIZE) as i32;
    add_hash(
        hash,
        (*universe).name as *mut u8,
        0,
        core::ptr::addr_of_mut!(dhcp_universe) as *mut u8,
    );
}
